// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 shapes[${g_numShapes}];

		const float WIDTH = ${(typeof windowWidth !== "undefined" && windowWidth ? Math.floor(windowWidth) : 1920)}.0;
		const float HEIGHT = ${(typeof windowHeight !== "undefined" && windowHeight ? Math.floor(windowHeight) : 1080)}.0;

		#define PI 3.1415926538

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;
			float v_solid = 0.0;

			bool rd = false;
			bool ln1 = false;
			bool ln2 = false;

			for (int i = 0; i < ${g_numShapes}; i++) {
				vec3 mtn = shapes[i];

				float dx = mtn.x - x;
				float dy = mtn.y - y;
				float r = mtn.z;
				float dsq = (dx*dx)+(dy*dy);

				v += r / sqrt(dsq);

				// Radial measure lines
				if (abs(dy) < 2.0 && abs(dx) < r) ln1 = true;
				if (abs(dy) < 2.0 && abs(dx) < (r*2.0)) ln2 = true;

				// Paint red dot at center
				if (dsq < 15.0) rd = true;
			}



			if (rd) gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);
			else if (ln1) gl_FragColor = vec4(0.0, 0.0, 1.0, 1.0);
			else if (ln2) gl_FragColor = vec4(0.0, 1.0, 0.0, 1.0);
			else if (v >= 1.0 && v <= 1.02) gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
			else gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
		}
	`;

	return createShader(vert, frag);
}

